#!/usr/bin/env bash
set -Eeuo pipefail

cd "$HOME/Downloads"
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/openmw51-visgrid-v22-1-upward-$STAMP"
mkdir -p "$OUT"
LOG="$OUT/controller.log"
exec > >(tee "$LOG") 2>&1

ROOT="/mnt/SDCARD/data/ports/openmw51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
DEST="$MOD/scripts/TSPInteriorVisGrid"
LUA="$DEST/visgrid.lua"
TOPO="$DEST/topology.lua"
DOOR="$DEST/doorgraph.lua"
DB="/mnt/UDISK/openmw51-nav/navmesh.db"
BIN="$ROOT/bin/openmw-0.51"

if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)

BASE_SHA="eb8331500d9ce7b638e79729a21477af5dffb9fb4c9bf7923c60a855452b3533"
NEW_SHA="6dabab5641894968b51c2a8399ac206926662d4182d8445bb710ef7a0e2a7c45"
PATCH_SHA="9aecf059a6e1d2ad966b4b3c972f4fe81aff8e50fdde9892ffbb823431913864"

cat <<'BANNER'
==================================================================
OPENMW 0.51 — VISGRID V22.1 UPWARD ANTICIPATION
==================================================================
Adds to the resident-room V22 sensor:
  - fast upward camera movement immediately raises the upper-screen Z floor
  - uses live camera-vector Z velocity (right stick OR mouse; no binding guess)
  - spends only 2 temporary extra rays, pitched ahead of the current view
  - deep/miss upper rays reinforce the prefetch and can promote resident rooms
  - 3 fresh close ceiling reports cancel speculative Z rendering quickly
  - a confirmed open-space report makes ceiling pullback require stronger evidence
  - a solid-ceiling pullback blocks immediate re-trigger for 0.35s
  - V22 resident-room policy and V21/V21.1 aperture memory remain intact

Only visgrid.lua is modified.
No OpenMW-running process check.
Game binary, topology, doorgraph and canonical navmesh DB are protected by
before/after snapshots.
==================================================================
BANNER

echo
echo "===== 1/7 FETCH LIVE SENSOR + SNAPSHOT PROTECTED STATE ====="
scp -q "${SSH[@]}" "$DEV:$LUA" "$OUT/live.lua"
LIVE_SHA="$(sha256sum "$OUT/live.lua" | awk '{print $1}')"
GAME_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
TOPO_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')"
DOOR_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$DOOR'" | awk '{print $1}')"
DB_BEFORE="$(ssh "${SSH[@]}" "$DEV" "stat -c '%s %Y' '$DB'")"

echo "sensor SHA:   $LIVE_SHA"
echo "game SHA:     $GAME_BEFORE"
echo "topology SHA: $TOPO_BEFORE"
echo "doorgraph SHA:$DOOR_BEFORE"
echo "DB size/mtime:$DB_BEFORE"

if [ "$LIVE_SHA" = "$NEW_SHA" ]; then
    echo "PASS: V22.1 is already installed; no sensor write needed."
    ALREADY=1
else
    ALREADY=0
    [ "$LIVE_SHA" = "$BASE_SHA" ] || {
        echo "ERROR: live sensor is not the exact V22 baseline this patch was self-tested against."
        echo "Expected V22: $BASE_SHA"
        echo "Live:         $LIVE_SHA"
        echo "Nothing changed."
        exit 20
    }
    grep -Fq 'TSP_VISGRID_LUA_V22_RESIDENT_SECTORS' "$OUT/live.lua"
    grep -Fq 'TSP_VISGRID_LUA_V21_1_STABLE_APERTURE' "$OUT/live.lua"
    echo "PASS: exact live V22 baseline verified."
fi

echo
echo "===== 2/7 RECREATE SELF-TESTED V22 -> V22.1 PATCHER ====="
cat > "$OUT/patch.py.b64" <<'PATCH_B64'

PATCH_B64
base64 -d "$OUT/patch.py.b64" > "$OUT/patch.py"
rm -f "$OUT/patch.py.b64"
chmod +x "$OUT/patch.py"
ACTUAL_PATCH_SHA="$(sha256sum "$OUT/patch.py" | awk '{print $1}')"
[ "$ACTUAL_PATCH_SHA" = "$PATCH_SHA" ] || {
    echo "ERROR: embedded patcher bytes differ."
    exit 21
}
python3 -m py_compile "$OUT/patch.py"
echo "PASS: embedded patcher SHA + Python syntax."

if [ "$ALREADY" -eq 0 ]; then
    echo
    echo "===== 3/7 GENERATE EXACT CANDIDATE FROM THE FETCHED LIVE V22 ====="
    cp -p "$OUT/live.lua" "$OUT/visgrid-v22.1.lua"
    python3 "$OUT/patch.py" "$OUT/visgrid-v22.1.lua"
    CAND_SHA="$(sha256sum "$OUT/visgrid-v22.1.lua" | awk '{print $1}')"
    echo "candidate SHA: $CAND_SHA"
    [ "$CAND_SHA" = "$NEW_SHA" ] || {
        echo "ERROR: candidate differs from the independently Lua-parse-validated V22.1 bytes."
        exit 22
    }
    grep -Fq 'TSP_VISGRID_LUA_V22_1_UPWARD_ANTICIPATION' "$OUT/visgrid-v22.1.lua"
    grep -Fq '[TSP_VISGRID_V22.1] upward anticipation loaded' "$OUT/visgrid-v22.1.lua"
    echo "PASS: candidate is exact pre-validated V22.1."
else
    cp -p "$OUT/live.lua" "$OUT/visgrid-v22.1.lua"
fi

echo
echo "===== 4/7 INSTALL SENSOR ONLY ====="
BACK="$MOD/visgrid-backups/visgrid-before-v22.1-$STAMP.lua"
if [ "$ALREADY" -eq 0 ]; then
    scp -q "${SSH[@]}" "$OUT/visgrid-v22.1.lua" "$DEV:$ROOT/visgrid-v22.1.lua.new"
    ssh "${SSH[@]}" "$DEV" "STAMP='$STAMP' bash -s" <<'REMOTE_INSTALL'
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
LUA="$MOD/scripts/TSPInteriorVisGrid/visgrid.lua"
NEW="$ROOT/visgrid-v22.1.lua.new"
BACK="$MOD/visgrid-backups/visgrid-before-v22.1-$STAMP.lua"
mkdir -p "$MOD/visgrid-backups"
test -s "$LUA"
test -s "$NEW"
cp -p "$LUA" "$BACK"
mv "$NEW" "$LUA"
sync
printf 'backup=%s\n' "$BACK"
REMOTE_INSTALL
else
    echo "No install needed."
fi

echo
echo "===== 5/7 VERIFY INSTALL + PROTECTED STATE ====="
LIVE_AFTER="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"
GAME_AFTER="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
TOPO_AFTER="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')"
DOOR_AFTER="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$DOOR'" | awk '{print $1}')"
DB_AFTER="$(ssh "${SSH[@]}" "$DEV" "stat -c '%s %Y' '$DB'")"

FAIL=0
[ "$LIVE_AFTER" = "$NEW_SHA" ] || FAIL=1
[ "$GAME_AFTER" = "$GAME_BEFORE" ] || FAIL=1
[ "$TOPO_AFTER" = "$TOPO_BEFORE" ] || FAIL=1
[ "$DOOR_AFTER" = "$DOOR_BEFORE" ] || FAIL=1
[ "$DB_AFTER" = "$DB_BEFORE" ] || FAIL=1

if [ "$FAIL" -ne 0 ]; then
    echo "ERROR: post-install verification failed."
    if [ "$ALREADY" -eq 0 ]; then
        echo "Rolling sensor back from: $BACK"
        ssh "${SSH[@]}" "$DEV" "cp -p '$BACK' '$LUA' && sync"
    fi
    echo "sensor expected: $NEW_SHA"
    echo "sensor actual:   $LIVE_AFTER"
    echo "game before/after: $GAME_BEFORE / $GAME_AFTER"
    echo "topology before/after: $TOPO_BEFORE / $TOPO_AFTER"
    echo "doorgraph before/after: $DOOR_BEFORE / $DOOR_AFTER"
    echo "DB before/after: $DB_BEFORE / $DB_AFTER"
    exit 23
fi

ssh "${SSH[@]}" "$DEV" "grep -F 'TSP_VISGRID_LUA_V22_1_UPWARD_ANTICIPATION' '$LUA' | head -1"
echo "PASS: V22.1 installed."
echo "PASS: game binary unchanged."
echo "PASS: topology unchanged."
echo "PASS: real-door graph unchanged."
echo "PASS: canonical navmesh DB unchanged."

echo
echo "===== 6/7 WRITE TRACE COLLECTOR ====="
cat > "$HOME/Downloads/pull-visgrid-v22-1-upward.sh" <<'EOF_PULL'
#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"
if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/visgrid-v22-1-upward-$STAMP.txt"
{
    echo "===== V22.1 INSTALL ====="
    ssh "${SSH[@]}" "$DEV" "sha256sum '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua'; grep -n 'TSP_VISGRID_LUA_V22_1_UPWARD_ANTICIPATION' '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua' | head -1"
    echo
    echo "===== V22.1 / RESIDENT / UPWARD SESSION ====="
    ssh "${SSH[@]}" "$DEV" "for f in '$ROOT/openmw_051_log.txt' '$ROOT/config-0.51/openmw.log'; do [ -s "\$f" ] || continue; echo; echo --- "\$f" ---; grep -hE 'TSP_VISGRID_V22\.1|TSP_VISGRID_V22|TSP_VISGRID_V21|TSP_VISGRID_V20|TSP_VISGRID_V15|TSP_VISGRID_V11|Lua.*ERROR|Lua.*error' "\$f" | tail -5000 || true; done"
} 2>&1 | tee "$OUT"
echo
echo "Saved: $OUT"
EOF_PULL
chmod +x "$HOME/Downloads/pull-visgrid-v22-1-upward.sh"
bash -n "$HOME/Downloads/pull-visgrid-v22-1-upward.sh"
echo "PASS: trace collector ready."

echo
echo "===== 7/7 COMPLETE ====="
echo "V22.1 sensor SHA: $NEW_SHA"
echo "Controller log:  $LOG"
echo "After restarting and testing the tower, collect with:"
echo "  cd ~/Downloads && ./pull-visgrid-v22-1-upward.sh"
echo "Watch status fields: v221=1 uzr= ub= upr= udeep= uclose= upb= uf="
echo "=================================================================="
